def vendor(root):
    """作者MIT源码原样内嵌；不在服务器运行时拉取可能变化的main。"""
    raw=zlib.decompress(base64.b85decode(VENDOR_B85))
    if hashlib.sha256(raw).hexdigest()!=VENDOR_SHA:raise RuntimeError('作者源码包不符')
    dest=Path(root)/'vendor'/UPSTREAM_COMMIT;dest.mkdir(parents=True,exist_ok=True)
    with tarfile.open(fileobj=io.BytesIO(raw),mode='r:') as tf:
        for item in tf:
            parts=PurePosixPath(item.name).parts
            if not item.isfile() or item.issym() or item.islnk() or '..' in parts or PurePosixPath(item.name).is_absolute():raise RuntimeError('作者源码包路径异常')
            p=dest.joinpath(*parts)
            blob=tf.extractfile(item).read()
            if hashlib.sha256(blob).hexdigest()!=VENDOR_FILE_HASHES[item.name]:raise RuntimeError('作者文件hash不符')
            p.parent.mkdir(parents=True,exist_ok=True)
            if p.exists() and p.read_bytes()!=blob:raise RuntimeError('既有作者副本被改动')
            if not p.exists():p.write_bytes(blob)
    return dest

def native_config(root,folder,task):
    dest=vendor(root);sys.path.insert(0,str(dest))
    import elements
    from ruamel.yaml import YAML
    import dreamerv3.main as dm
    raw=YAML(typ='safe').load((dest/'dreamerv3/configs.yaml').read_text(encoding='utf-8'))
    # 半分钟只是决策记录单位；每两次记录的折扣仍为原.99，不更改真实物理时间。
    raw['defaults']['agent']['horizon']=1/(1-math.sqrt(.99))
    cfg=elements.Config(raw['defaults']).update(raw['size1m'])
    cfg=cfg.update(dict(logdir=str(folder/'native'),seed=int(task['seed']),
        batch_size=16,batch_length=64,report_length=64,replay_context=1,
        **{'jax.platform':'cuda','jax.prealloc':False,
           'logger.outputs':['jsonl'],'replay.size':100000,
           'agent.imag_length':30 if task['arm']=='DV3_H15MIN' else 2,
           'agent.contdisc':False,'run.train_ratio':32.,'run.envs':1,'run.debug':True}))
    cfg.save(elements.Path(folder/'NATIVE_CONFIG.yaml'))
    save(folder/'CONFIG.json',dict(upstream_commit=UPSTREAM_COMMIT,size='size1m',train_ratio=32,
        imag_length=30 if task['arm']=='DV3_H15MIN' else 2,horizon=1/(1-math.sqrt(.99)),
        config_file='NATIVE_CONFIG.yaml',two_decisions_per_physical_minute=True))
    return cfg,dm

def install_quality_report():
    """只扩充冻结评估报告，不改变作者训练损失、RSSM或策略更新。"""
    from dreamerv3.agent import Agent
    if getattr(Agent,'_uam_quality_report',False):return
    original=Agent.report
    def report(self,carry,data):
        import jax
        import jax.numpy as jnp
        result,mets=original(self,carry,data)
        initial,obs,actions,_=self._apply_replay_context(carry,data)
        enc_carry,dyn_carry,dec_carry=initial
        _,_,tokens=self.enc(enc_carry,obs,obs['is_first'],training=False)
        length=obs['is_first'].shape[1];half=length//2
        take=lambda tree:jax.tree.map(lambda x:x[:,:half],tree)
        rest=lambda tree:jax.tree.map(lambda x:x[:,half:],tree)
        dyn_carry,_,feat=self.dyn.observe(dyn_carry,take(tokens),take(actions),take(obs['is_first']),training=False)
        dec_carry,_,_=self.dec(dec_carry,feat,take(obs['is_first']),training=False)
        _,future,_=self.dyn.imagine(dyn_carry,rest(actions),length=length-half,training=False)
        _,_,recons=self.dec(dec_carry,future,jnp.zeros_like(rest(obs['is_first'])),training=False)
        error=recons['vector'].pred()-obs['vector'][:,half:]
        # 误差按完整episode采样；跨episode的未来窗口必须剔除，不能伪造连续预测。
        valid=jnp.cumprod((~obs['is_first'][:,half:]).astype(jnp.float32),axis=1)
        sq=jnp.mean(error**2,axis=-1)
        mets['uam/openloop_vector_rmse']=jnp.sqrt((sq*valid).sum()/jnp.maximum(1.,valid.sum()))
        mets['uam/valid_prediction_records']=valid.sum()
        for minute in (1,5,15):
            i=min(error.shape[1]-1,minute*2-1);mask=valid[:,i]
            mets[f'uam/vector_rmse_{minute}min']=jnp.sqrt((sq[:,i]*mask).sum()/jnp.maximum(1.,mask.sum()))
        return result,mets
    Agent.report=report;Agent._uam_quality_report=True

def embodied_env_class(m,root,task,trace,horizon,seed):
    import elements,embodied,numpy as np
    PhaseEnv=gym_class(m)
    class Wrapped(embodied.Env):
        def __init__(self):
            self.raw=PhaseEnv(root,task,trace,horizon,seed,False);self.done=True;self.info={}
        @property
        def obs_space(self):
            return dict(vector=elements.Space(np.float32,self.raw.observation_space.shape),
                reward=elements.Space(np.float32),is_first=elements.Space(bool),
                is_last=elements.Space(bool),is_terminal=elements.Space(bool))
        @property
        def act_space(self):return dict(reset=elements.Space(bool),action=elements.Space(np.int32,(),0,3))
        def step(self,action):
            if bool(action['reset']) or self.done:
                obs,_=self.raw.reset();reward=0.;first=True;last=False;inc=0
            else:
                obs,reward,terminated,last,self.info=self.raw.step(int(action['action']));first=False
                inc=int(self.info['physical_increment'])
            self.done=bool(last)
            result=dict(vector=obs,reward=np.float32(reward),is_first=np.bool_(first),
                is_last=np.bool_(last),is_terminal=np.bool_(False))
            # 全员服务完成才是终止；500/600分钟时限保留为截断，不伪造终止。
            if last and self.raw.last_episode and self.raw.last_episode['unfinished']==0:result['is_terminal']=np.bool_(True)
            result['log/physical_increment']=np.int32(inc)
            return result
        def close(self):self.raw.close()
    return Wrapped

def train_native(job):
    root=Path(job['root']);task=job['task'];folder=root/'cells'/task['id'];folder.mkdir(parents=True,exist_ok=True)
    os.environ.setdefault('XLA_PYTHON_CLIENT_PREALLOCATE','false')
    os.environ.setdefault('XLA_PYTHON_CLIENT_MEM_FRACTION',str(job.get('gpu_fraction',.45)))
    m,_=runtime(root,task);cfg,dm=native_config(root,folder,task)
    import elements,embodied,numpy as np
    install_quality_report()
    from dreamerv3.agent import Agent
    Wrapped=embodied_env_class(m,root,task,job['trace'],500,task['seed'])
    probe=Wrapped();obs_space=probe.obs_space;act_space={k:v for k,v in probe.act_space.items() if k!='reset'};probe.close()
    agent=Agent(obs_space,act_space,elements.Config(**cfg.agent,logdir=cfg.logdir,seed=cfg.seed,jax=cfg.jax,
        batch_size=cfg.batch_size,batch_length=cfg.batch_length,replay_context=cfg.replay_context,
        report_length=cfg.report_length,replica=0,replicas=1))
    replay=dm.make_replay(cfg,'replay');replay.save_wait=True
    driver=embodied.Driver([Wrapped],parallel=False)
    pointer=read(folder/'RESUME.json',{})
    state=dict(real_steps=0,decision_records=0,gradient_updates=0,imagined_transitions=0)
    if pointer:
        if digest(folder/pointer['model'])!=pointer['model_sha']:raise RuntimeError('Dreamer恢复件不符')
        with (folder/pointer['model']).open('rb') as f:record=pickle.load(f)
        agent.load(record['agent']);state.update(record['counts']);replay.load()
    elif (folder/'RESUME.pkl').exists():raise RuntimeError('存在Dreamer模型但缺指针，不覆盖')
    stream=iter(agent.stream(dm.make_stream(cfg,replay,'train')))
    carry=agent.init_train(cfg.batch_size);started=time.time();last_save=started;last_report=started
    initial=state['real_steps'];last_checkpoint=initial;last_mets={}
    def checkpoint(name='RESUME'):
        replay.save()
        model_path=folder/(name+'.pkl')
        checkpoint_pickle(model_path,dict(agent=agent.save(),counts=dict(state),native_commit=UPSTREAM_COMMIT))
        save(folder/(name+'.json'),dict(model=model_path.name,model_sha=digest(model_path),**state))
    def on_step(tran,worker):
        nonlocal last_save,last_report,last_checkpoint,carry,last_mets
        state['real_steps']+=int(tran.get('log/physical_increment',0));state['decision_records']+=1
        replay.add(tran,worker)
        # 与作者训练比例定义相同：每新增一条决策记录对应32条采样训练记录。
        desired=int(state['decision_records']*float(cfg.run.train_ratio)/(cfg.batch_size*cfg.batch_length))
        if len(replay)>=cfg.batch_size*cfg.batch_length:
            while state['gradient_updates']<desired:
                carry,outs,mets=agent.train(carry,next(stream));last_mets=mets;state['gradient_updates']+=1
                state['imagined_transitions']+=cfg.batch_size*cfg.batch_length*cfg.agent.imag_length
                if 'replay' in outs:replay.update(outs['replay'])
                if time.time()>=job['deadline']-300:break
            if time.time()-last_report>120:
                save(folder/'NATIVE_METRICS.json',dict(metrics=last_mets,counts=state));last_report=time.time()
        if time.time()-last_save>300:
            checkpoint();last_save=time.time()
        if state['real_steps']-last_checkpoint>=20480:
            checkpoint(f'CP_{state["real_steps"]:09d}');last_checkpoint=state['real_steps']
        if state['decision_records']%100==0:
            save(folder/'LIVE.json',dict(phase='native_train',**state,seconds=time.time()-started,
                real_fps=(state['real_steps']-initial)/max(1,time.time()-started),time=time.time()))
    driver.on_step(on_step);driver.reset(agent.init_policy)
    try:
        policy=lambda *args:agent.policy(*args,mode='train')
        while state['real_steps']<job['steps'] and time.time()<job['deadline']-300 and not (root/'STOP_REQUESTED').exists():
            driver(policy,steps=1)
        checkpoint();status='COMPLETE' if state['real_steps']>=job['steps'] else 'PARTIAL'
        save(folder/'TRAIN_END.json',dict(status=status,**state,seconds=time.time()-started))
    finally:driver.close()
    # 保存后再做最终评估；即使时限不足目标，也把PARTIAL的真实固定存档结果单独保留。
    evaluate_native(job,agent=agent,m=m,cfg=cfg)
    save(folder/'END.json',dict(status=status,**state,seconds=time.time()-started,
        native_commit=UPSTREAM_COMMIT,algorithm='作者DreamerV3重实现，RSSM/想象actor-critic/原优化器均保留',
        boundary='未达到目标者不可混入满预算排名；不把想象样本计为真实交互'))

def evaluate_native(job,agent=None,m=None,cfg=None):
    import numpy as np
    root=Path(job['root']);task=job['task'];folder=root/'cells'/task['id']
    if m is None:m,_=runtime(root,task)
    if cfg is None:cfg,dm=native_config(root,folder,task)
    import elements
    install_quality_report()
    from dreamerv3.agent import Agent
    if agent is None:
        Wrapped=embodied_env_class(m,root,task,job['trace'],600,123);probe=Wrapped()
        agent=Agent(probe.obs_space,{k:v for k,v in probe.act_space.items() if k!='reset'},
            elements.Config(**cfg.agent,logdir=cfg.logdir,seed=cfg.seed,jax=cfg.jax,batch_size=cfg.batch_size,
                batch_length=cfg.batch_length,replay_context=cfg.replay_context,report_length=cfg.report_length,replica=0,replicas=1))
        probe.close();pointer=read(folder/'RESUME.json')
        with (folder/pointer['model']).open('rb') as f:agent.load(pickle.load(f)['agent'])
    pointer=read(folder/'RESUME.json')
    with (folder/pointer['model']).open('rb') as f:agent.load(pickle.load(f)['agent'])
    import embodied
    rows=[];holdout=embodied.replay.Replay(length=65,capacity=20000,online=False)
    for bank in job['bank']:
        Wrapped=embodied_env_class(m,root,task,bank['path'],600,123);env=Wrapped();carry=agent.init_policy(1)
        obs=env.step(dict(reset=True,action=0))
        try:
            while not env.done:
                batched={k:np.asarray([v]) for k,v in obs.items() if not k.startswith('log/')}
                carry,act,outs=agent.policy(carry,batched,mode='eval')
                transition={**{k:np.asarray(v) for k,v in obs.items() if not k.startswith('log/')},
                    **{k:np.asarray(v[0]) for k,v in act.items()},**{k:np.asarray(v[0]) for k,v in outs.items()}}
                holdout.add(transition,worker=0)
                obs=env.step(dict(reset=False,action=int(act['action'][0])))
            rows.append(dict(trace=bank['name'],trace_sha256=bank['sha256'],metrics=env.raw.last_episode))
        finally:env.close()
    dm=__import__('dreamerv3.main',fromlist=['make_stream'])
    predictions=[]
    if len(holdout)>=cfg.batch_size*cfg.report_length:
        stream=iter(agent.stream(dm.make_stream(cfg,holdout,'report')));carry=agent.init_report(cfg.batch_size)
        for _ in range(4):
            carry,mets=agent.report(carry,next(stream));predictions.append(mets)
    save(folder/'WORLD_MODEL_FIT.json',dict(holdout_reports=predictions,new_optimizer_updates=0,
        scope='冻结模型在未用于梯度更新的验证轨迹上，按已实现动作测1/5/15分钟预测误差；不是在线偷看未来，也不是候选排序正确的证明'))
    save(folder/'EVALUATION.json',dict(task=task,final=rows,mode='作者原生随机策略；普通PPO匹配随机评估',
        checkpoint='固定最终/时限存档，不按Best选择',new_training_transitions=0,
        limitation='模型预测误差见WORLD_MODEL_FIT.json；准确不等于决策更好，必须与整场和逐人收益共同判断'))

def harl_prepare(job):
    """只导入用户另行下载的作者副本；未见明确许可证，故不再分发其源码。"""
    dest=Path(job['harl_dir']).resolve()
    check=subprocess.run(['git','-C',str(dest),'rev-parse','HEAD'],capture_output=True,text=True)
    if check.returncode or check.stdout.strip()!=HARL_COMMIT:raise RuntimeError('HARL作者版本不符；见上传启动说明中的固定版本下载命令')
    changed=subprocess.run(['git','-C',str(dest),'diff','--name-only','HEAD'],capture_output=True,text=True)
    if changed.returncode or changed.stdout.strip():raise RuntimeError('HARL作者源码存在改动，不混用')
    sys.path.insert(0,str(dest))
    import yaml
    config=yaml.safe_load((dest/'harl/configs/algos_cfgs/happo.yaml').read_text(encoding='utf-8'))
    args={**config['model'],**config['algo'],**config['train']}
    args.update(episode_length=2048,n_rollout_threads=5,actor_num_mini_batch=20,critic_num_mini_batch=20,
        gamma=.99,gae_lambda=.95,use_recurrent_policy=False,use_naive_recurrent_policy=False)
    # 原作者更新函数原样抽取执行，避免其通用runner额外导入星际等无关环境。
    path=dest/'harl/runners/on_policy_ha_runner.py'
    tree=ast.parse(path.read_text(encoding='utf-8'))
    cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='OnPolicyHARunner')
    fn=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='train')
    import numpy as np,torch
    ns=dict(np=np,torch=torch,_t2n=lambda x:x.detach().cpu().numpy())
    exec(compile(ast.fix_missing_locations(ast.Module(body=[fn],type_ignores=[])),str(path),'exec'),ns)
    return dest,args,ns['train']

def train_harl(job):
    """一物理分钟收集乘客→飞机两个动作，原生HAPPO校正不能在交替空动作上退化。"""
    import numpy as np,torch,gymnasium as gym
    from stable_baselines3.common.vec_env import SubprocVecEnv,VecNormalize
    root=Path(job['root']);task=job['task'];folder=root/'cells'/task['id'];started=time.time()
    dest,args,author_train=harl_prepare(job)
    from harl.algorithms.actors.happo import HAPPO
    from harl.algorithms.actors.mappo import MAPPO
    from harl.algorithms.critics.v_critic import VCritic
    from harl.common.buffers.on_policy_actor_buffer import OnPolicyActorBuffer
    from harl.common.buffers.on_policy_critic_buffer_ep import OnPolicyCriticBufferEP
    from harl.common.valuenorm import ValueNorm
    m,_=runtime(root,task);PhaseEnv=gym_class(m)
    torch.manual_seed(task['seed']);np.random.seed(task['seed']);random.seed(task['seed'])
    if job['device']=='cuda':torch.cuda.set_per_process_memory_fraction(job.get('gpu_fraction',.45),0)
    def maker(rank):
        def ctor():return PhaseEnv(root,task,job['trace'],500,task['seed']*10+rank,False)
        return ctor
    vector=SubprocVecEnv([maker(i) for i in range(5)],start_method='spawn')
    pointer=read(folder/'RESUME.json',{})
    if pointer:
        if digest(folder/pointer['model'])!=pointer['model_sha'] or digest(folder/pointer['norm'])!=pointer['norm_sha']:raise RuntimeError('HARL恢复文件hash不符')
        with (folder/pointer['model']).open('rb') as f:record=pickle.load(f)
        norm=VecNormalize.load(str(folder/record['norm']),vector)
    else:
        record={};norm=VecNormalize(vector,norm_obs=True,norm_reward=False)
    device=torch.device(job['device']);space=norm.observation_space;act_space=gym.spaces.Discrete(3)
    Actor=HAPPO if task['arm']=='HAPPO_NATIVE' else MAPPO
    actors=[Actor(args,space,act_space,device=device) for _ in range(2)]
    critic=VCritic(args,space,device=device);value_norm=ValueNorm(1,device=device)
    if record:
        for i,a in enumerate(actors):a.actor.load_state_dict(record['actors'][i]);a.actor_optimizer.load_state_dict(record['optimizers'][i])
        critic.critic.load_state_dict(record['critic']);critic.critic_optimizer.load_state_dict(record['critic_optimizer'])
        value_norm.load_state_dict(record['value_norm'])
        for key,tensor in record.get('value_norm_statistics',{}).items():getattr(value_norm,key).copy_(tensor.to(device))
        torch.set_rng_state(record['torch_rng']);np.random.set_state(record['numpy_rng']);random.setstate(record['python_rng'])
        if job['device']=='cuda' and record.get('cuda_rng') is not None:torch.cuda.set_rng_state_all(record['cuda_rng'])
    real=int(record.get('real_steps',0));initial=real;updates=int(record.get('updates',0));last_cp=real
    buffers=[OnPolicyActorBuffer(args,space,act_space) for _ in range(2)]
    cb=OnPolicyCriticBufferEP(args,space)
    runner=types.SimpleNamespace(algo_args={'train':args},actor=actors,critic=critic,actor_buffer=buffers,
        critic_buffer=cb,value_normalizer=value_norm,state_type='EP',fixed_order=False,num_agents=2,action_aggregation='prod')
    obs=norm.reset();zeros=np.zeros((5,1,128),np.float32);ones=np.ones((5,1),np.float32);masks=ones.copy()
    def snapshot(name='RESUME'):
        norm_path=folder/(name+'.norm.pkl');norm.save(str(norm_path))
        payload=dict(real_steps=real,updates=updates,actors=[a.actor.state_dict() for a in actors],
            optimizers=[a.actor_optimizer.state_dict() for a in actors],critic=critic.critic.state_dict(),
            critic_optimizer=critic.critic_optimizer.state_dict(),value_norm=value_norm.state_dict(),
            value_norm_statistics={key:getattr(value_norm,key).detach().cpu() for key in ('running_mean','running_mean_sq','debiasing_term')},norm=norm_path.name,
            torch_rng=torch.get_rng_state(),cuda_rng=torch.cuda.get_rng_state_all() if job['device']=='cuda' else None,
            numpy_rng=np.random.get_state(),python_rng=random.getstate(),harl_commit=HARL_COMMIT)
        checkpoint_pickle(folder/(name+'.pkl'),payload)
        save(folder/(name+'.json'),dict(model=name+'.pkl',model_sha=digest(folder/(name+'.pkl')),
            norm=norm_path.name,norm_sha=digest(norm_path),real_steps=real,decision_records=2*real))
    save(folder/'CONFIG.json',dict(author_commit=HARL_COMMIT,args=args,
        actor_observation='乘客读pre；飞机在同分钟的prepare之后读post，critic只读pre，不读未揭示未来',
        update='作者HAPPO顺序更新函数原样执行' if task['arm']=='HAPPO_NATIVE' else '相同两actor/critic/归一化/动作，去除前序策略比值校正的MAPPO对照',
        limitation='原生MLP及ValueNorm，与共享Transformer PPO的比较是完整方案比较；不是纯更新因果对照',
        resume='恢复模型、优化器、归一化、计数与随机状态；仿真从新episode重启，不声称位级续接'))
    try:
        while real<job['steps'] and time.time()<job['deadline']-300 and not (root/'STOP_REQUESTED').exists():
            for b in buffers:b.step=0;b.factor=None
            cb.step=0
            for a in actors:a.prep_rollout();a.lr_decay(real,max(1,job['steps']))
            critic.prep_rollout();critic.lr_decay(real,max(1,job['steps']))
            for k in range(args['episode_length']):
                with torch.no_grad():
                    values,_=critic.get_values(obs,zeros,masks)
                    ap,lp,_=actors[0].get_actions(obs,zeros,masks)
                buffers[0].obs[k]=obs;buffers[0].masks[k]=masks;cb.share_obs[k]=obs
                mid,rew,done,infos=norm.step(ap.detach().cpu().numpy().ravel())
                if any(done) or np.any(rew):raise RuntimeError('乘客准备阶段不应推进物理或产生奖励')
                with torch.no_grad():aa,la,_=actors[1].get_actions(mid,zeros,masks)
                buffers[1].obs[k]=mid;buffers[1].masks[k]=masks
                nxt,rewards,dones,infos=norm.step(aa.detach().cpu().numpy().ravel())
                if any(info.get('physical_increment')!=1 for info in infos):raise RuntimeError('HARL真实步数不符')
                nxt_masks=(~dones).astype(np.float32)[:,None]
                # 时限截断使用原生bad_mask，不把未完成者当终止；保留原人时奖励。
                bad=np.asarray([[0. if info.get('TimeLimit.truncated',False) else 1.] for info in infos],np.float32)
                for b,action,logp in zip(buffers,(ap,aa),(lp,la)):
                    b.insert(nxt,zeros,action.detach().cpu().numpy(),logp.detach().cpu().numpy(),nxt_masks,ones)
                cb.insert(nxt,zeros,values.detach().cpu().numpy(),rewards[:,None],nxt_masks,bad)
                obs=nxt;masks=nxt_masks;real+=5
            with torch.no_grad():next_value,_=critic.get_values(obs,zeros,masks)
            cb.compute_returns(next_value.detach().cpu().numpy(),value_norm)
            for a in actors:a.prep_training()
            critic.prep_training()
            if task['arm']=='HAPPO_NATIVE':actor_metrics,critic_metrics=author_train(runner)
            else:
                adv=cb.returns[:-1]-value_norm.denormalize(cb.value_preds[:-1])
                actor_metrics=[a.train(b,adv.copy(),'EP') for a,b in zip(actors,buffers)]
                critic_metrics=critic.train(cb,value_norm)
            updates+=1;snapshot()
            factors=[b.factor for b in buffers if b.factor is not None]
            save(folder/'UPDATE_AUDIT.json',dict(updates=updates,actor_metrics=actor_metrics,critic_metrics=critic_metrics,
                factor_nontrivial_fraction=max([float(np.mean(np.abs(factor-1)>1e-5)) for factor in factors] or [0.]),
                explanation='HAPPO每行包含两个真实动作，避免在轮流Noop行上将校正项退化为1；随机更新顺序不等于环境动作顺序'))
            if real-last_cp>=20480:snapshot(f'CP_{real:09d}');last_cp=real
            save(folder/'LIVE.json',dict(phase='train',real_steps=real,updates=updates,seconds=time.time()-started,
                real_fps=(real-initial)/max(1,time.time()-started)))
        snapshot();status='COMPLETE' if real>=job['steps'] else 'PARTIAL'
        def predict(x,state):
            phase=int(round(float(x[-8])));a=actors[phase]
            with torch.no_grad():action,_,_=a.get_actions(norm.normalize_obs(np.asarray(x)[None]),zeros[:1],ones[:1])
            return int(action.detach().cpu().numpy()[0,0]),None
        for a in actors:a.prep_rollout()
        result=evaluate_predictor(m,root,task,job['bank'],predict,False)
        save(folder/'EVALUATION.json',dict(task=task,real_steps=real,final=result,mode='匹配随机策略',new_training_transitions=0))
        save(folder/'END.json',dict(status=status,real_steps=real,updates=updates,seconds=time.time()-started,
            author_commit=HARL_COMMIT,weight_model_sha256=digest(folder/'RESUME.pkl')))
    finally:norm.close()

def hot_tasks():
    result=[];rng=random.Random(20261104)
    for seed in SEEDS:
        arms=list(HOT_HOURS);rng.shuffle(arms)
        for name in arms:result.append(task_record(name,seed,space=True,temporal=False))
    return result

def main():
    ap=argparse.ArgumentParser(description='40小时两条真实迁移：DreamerV3与HAPPO，另有PPO和同结构MAPPO对照')
    ap.add_argument('--resume',action='store_true');ap.add_argument('--worker');ap.add_argument('--plan',action='store_true')
    ap.add_argument('--device',choices=('cpu','cuda'),default='cuda');ap.add_argument('--wall-hours',type=float,default=40.)
    ap.add_argument('--gpu-fraction',type=float,default=.45);ap.add_argument('--min-free-gib',type=float,default=8.)
    ap.add_argument('--ppo-python',default='/home/SY/wyw/conda/envs/uam_server/bin/python')
    ap.add_argument('--harl-dir',default=str(PROJECT/'workspace/vendor/HARL'))
    args=ap.parse_args();tasks=hot_tasks()
    if args.plan:
        print(json.dumps(dict(tasks=tasks,steps_ceiling=HOT_STEPS,total_real_step_ceiling=len(tasks)*HOT_STEPS,
            wall_hours=40,native_commit=UPSTREAM_COMMIT,harl_commit=HARL_COMMIT,per_seed_hours=HOT_HOURS,
            caution='两正式方法+两对照，共16格；40小时是时间上限，世界模型吞吐未经本地测量，不保证满训'),ensure_ascii=False,indent=2));return
    if args.worker:
        j=read(args.worker)
        try:
            if j['kind']=='ppo':train_ppo(j)
            elif j['kind']=='ppo_eval':eval_ppo(j)
            elif j['kind']=='harl':train_harl(j)
            else:train_native(j)
        except Exception:
            save(Path(j['root'])/'cells'/j['task']['id']/f'EXCEPTION_{time.time_ns()}.json',dict(traceback=traceback.format_exc()));raise
        return
    if args.device!='cuda':raise RuntimeError('作者世界模型使用JAX CUDA，不能静默降为CPU')
    if not 0<args.wall_hours<=40:raise RuntimeError('单会话预算最多40小时')
    root=PROJECT/'serial_runs/uam_hot_transfer_16run_40h_v1';root.mkdir(parents=True,exist_ok=True);lock=lock_root(root)
    m,native=runtime(root,tasks[0]);trace,bank=bank_make(root,native);start=time.time();deadline=start+args.wall_hours*3600-120
    contract(root,dict(tasks=tasks,step_ceiling=HOT_STEPS,upstream_commit=UPSTREAM_COMMIT,upstream_bundle_sha256=VENDOR_SHA,
        native_size='size1m',train_ratio=32,imaginary_minutes=[15],two_stage_discount=math.sqrt(.99),
        harl_commit=HARL_COMMIT,per_seed_hours=HOT_HOURS,
        bank=bank,action_contract='原目标优先级；无主动等待；所有方法相同合法意图解码',
        independent_replicates='4个优化种子；验证顺序不是训练种子'),args.resume)
    preflight(root,'cuda',args.min_free_gib)
    for i,t in enumerate(tasks):
        if time.time()>deadline:break
        folder=root/'cells'/t['id'];folder.mkdir(parents=True,exist_ok=True);save(folder/'TASK.json',t)
        # 每格时间配额相同，避免第一个热点耗尽全矩阵；不会因结果差而替换方法。
        cell_deadline=min(deadline,time.time()+HOT_HOURS[t['arm']]*(args.wall_hours/40)*3600-30)
        job=dict(root=str(root),task=t,steps=HOT_STEPS,extended=False,trace=trace,bank=bank,device='cuda',
            deadline=cell_deadline,gpu_fraction=args.gpu_fraction,eval_steps=[20480,40960,81920,163840,200704,401408,602112,802816,1003520],
            stochastic_eval=True,harl_dir=args.harl_dir,
            kind='ppo' if t['arm']=='PPO_TF' else 'harl' if t['arm'] in ('HAPPO_NATIVE','MAPPO_MATCHED') else 'native')
        save(folder/'JOB.json',job);python=args.ppo_python if job['kind'] in ('ppo','harl') else sys.executable
        print(f'[热点训练 {i+1}/{len(tasks)}]',t['id'],flush=True)
        if not (folder/'END.json').exists() or read(folder/'END.json').get('status')!='COMPLETE':
            with (folder/'worker.log').open('a',encoding='utf-8') as log:
                proc=subprocess.Popen([python,'-B','-u',__file__,'--worker',str(folder/'JOB.json')],cwd=PROJECT,stdout=log,stderr=subprocess.STDOUT)
                while proc.poll() is None:
                    save(root/'RUNNING.json',dict(task=t,pid=proc.pid,live=read(folder/'LIVE.json',{}),time=time.time()))
                    if time.time()>cell_deadline+30 or (root/'STOP_REQUESTED').exists():
                        proc.terminate()
                        try:proc.wait(timeout=30)
                        except subprocess.TimeoutExpired:proc.kill();proc.wait()
                        break
                    time.sleep(2)
                if proc.returncode:save(folder/f'FAILED_{time.time_ns()}.json',dict(exit_code=proc.returncode))
        if t['arm']=='PPO_TF' and (folder/'RESUME.json').exists() and not (folder/'EVALUATION.json').exists():
            job['kind']='ppo_eval';save(folder/'EVAL_JOB.json',job)
            with (folder/'eval.log').open('a',encoding='utf-8') as log:
                result=subprocess.run([python,'-B','-u',__file__,'--worker',str(folder/'EVAL_JOB.json')],cwd=PROJECT,stdout=log,stderr=subprocess.STDOUT)
            if result.returncode:save(folder/f'FAILED_EVAL_{time.time_ns()}.json',dict(exit_code=result.returncode))
        aggregate(root,tasks)
    p=aggregate(root,tasks);status='COMPLETE' if p['completed']==len(tasks) and p['evaluated']==len(tasks) else 'PARTIAL'
    save(root/'END.json',dict(status=status,progress=p,session_seconds=time.time()-start,
        note='不以各自不同步数的时限存档冒充等交互预算胜负；共同存档与等时间结果另列'))
    save(root/'RUNNING.json',dict(phase=status.lower(),pid=None,time=time.time()));pack_outputs(root);lock.close()

if __name__=='__main__':main()
